def mesh(name,v,f,m):
 v=np.array(v,float);f=np.array(f,int); center=v.mean(axis=0)
 for face in f:
  a,b,c=v[face];n=np.cross(b-a,c-a)
  if np.dot(n,(a+b+c)/3-center)<0: b,c=c,b
  if np.linalg.norm(n)>1e-10:tri.append((a,b,c,m))
 objects.append((name,v.tolist(),f.tolist(),m))
def box(name,pos,dim,m,bevel=0,rot=0):
 x,y,z=np.array(dim)/2; r=min(bevel,x*.9,y*.9,z*.9); pts=[]
 if r>0:
  for i in (-1,1):
   for j in (-1,1):
    for k in (-1,1):
     pts.extend([(i*x,j*(y-r),k*(z-r)),(i*(x-r),j*y,k*(z-r)),(i*(x-r),j*(y-r),k*z)])
 else:pts=[(i*x,j*y,k*z) for i in (-1,1) for j in (-1,1) for k in (-1,1)]
 v=np.array(pts);f=ConvexHull(v).simplices
 c,s=math.cos(rot),math.sin(rot);v=v@np.array([[c,s,0],[-s,c,0],[0,0,1]])+pos
 mesh(name,v,f,m)
def rounded(name,pos,dim,m,r=.06,rot=0,tilt=0):
 half=np.array(dim)/2;r=min(r,min(half)*.92);pts=[]
 for i in (-1,1):
  for j in (-1,1):
   for k in (-1,1):
    for a in np.linspace(0,math.pi/2,5):
     for b in np.linspace(0,math.pi/2,5):pts.append([i*(half[0]-r+r*math.cos(a)*math.cos(b)),j*(half[1]-r+r*math.sin(a)*math.cos(b)),k*(half[2]-r+r*math.sin(b))])
 v=np.unique(np.round(pts,7),axis=0);f=ConvexHull(v).simplices
 ct,st=math.cos(tilt),math.sin(tilt);v=v@np.array([[1,0,0],[0,ct,st],[0,-st,ct]])
 c,ss=math.cos(rot),math.sin(rot);v=v@np.array([[c,ss,0],[-ss,c,0],[0,0,1]])+pos;mesh(name,v,f,m)
def cylinder(name,a,b,r,m,r2=None,n=40):
 a,b=np.array(a,float),np.array(b,float);w=b-a;w/=np.linalg.norm(w);u=np.cross(w,[0,0,1] if abs(w[2])<.95 else [0,1,0]);u/=np.linalg.norm(u);v=np.cross(w,u);r2=r if r2 is None else r2
 verts=[p+rr*(math.cos(i*math.tau/n)*u+math.sin(i*math.tau/n)*v) for p,rr in [(a,r),(b,r2)] for i in range(n)];faces=[]
 for i in range(n):j=(i+1)%n;faces.extend([(i,j,n+j),(i,n+j,n+i)])
 for i in range(1,n-1):faces.extend([(0,i,i+1),(n,n+i+1,n+i)])
 mesh(name,verts,faces,m)
def ring(name,center,r,tube,m,segments=72,sides=10):
 # vertical circle in XZ plane
 cx,cy,cz=center;v=[];f=[]
 for i in range(segments):
  a=i*math.tau/segments
  for j in range(sides):
   b=j*math.tau/sides;rr=r+tube*math.cos(b);v.append((cx+rr*math.cos(a),cy+tube*math.sin(b),cz+rr*math.sin(a)))
 for i in range(segments):
  for j in range(sides):a=i*sides+j;b=((i+1)%segments)*sides+j;c=((i+1)%segments)*sides+(j+1)%sides;d=i*sides+(j+1)%sides;f.extend([(a,b,c),(a,c,d)])
 mesh(name,v,f,m)
def light(pos,aim,width,height,power,color=(1,.73,.46)):
 n=np.array(aim,float)-pos;n/=np.linalg.norm(n);u=np.cross(n,[0,0,1] if abs(n[2])<.95 else [0,1,0]);u/=np.linalg.norm(u);v=np.cross(n,u);lights.append([list(pos),list(u*width/2),list(v*height/2),list(n),[power*c for c in color]])
