def R(n,x,y,a,loc,dim,m,r=.04,tilt=0):rounded(n,tr(x,y,a,*loc),dim,m,r,a,tilt)
def C(n,x,y,a,p,q,r,m,r2=None,nseg=18):cylinder(n,tr(x,y,a,*p),tr(x,y,a,*q),r,m,r2,nseg)
